$twig->addFunction(new \Twig\TwigFunction('__', function($file, $key = null) {
    if(function_exists('__')) {
        return __($file, $key = null);
    }
    return null;
}));
$twig->addFunction(new \Twig\TwigFunction('route', function($file, $key = []) {
    if(function_exists('route')) {
        return route($file, $key);
    }
    return null;
}));
$twig->addFunction(new \Twig\TwigFunction('do_action', function($file, $key = []) {
    if(function_exists('do_action')) {
        return do_action($file, $key);
    }
    return null;
}));
$twig->addFunction(new \Twig\TwigFunction('controller', function($file, $args) {
    if(function_exists('controller')) {
        if ($args) {
            return registry()->get('load')->controller($file, $args);
        } else {
            return registry()->get('load')->controller($file);
        }
    }
    return null;
}));

/**
 * Получить экземпляр реестра
 * 
 * @return Registry
 */
public static function getInstance() {
    if (self::$instance === null) {
        self::$instance = new Registry();
    }
    return self::$instance;
}

public static function setInstance(Registry $instance) {
    self::$instance = $instance;
}

// OCMOD Обновляем статический экземпляр
if (self::$instance === null) {
    self::$instance = $this;
}
// OCMOD END

// Global helper function для новой системы хуков
if (is_file(DIR_SYSTEM . 'helper/gdt_helper.php')) {
    require_once(DIR_SYSTEM . 'helper/gdt_helper.php');

if (is_file(DIR_SYSTEM . 'library/gbitstudio/gdt/engine/gdt.php')) {
    require_once(DIR_SYSTEM . 'library/gbitstudio/gdt/engine/gdt.php');
}

// Инициализация GDT Framework и загрузка хуков из admin/controller/hook/
try {
    require_once(DIR_SYSTEM . 'library/gbitstudio/gdt/engine/gdthelper.php');
    \GbitStudio\GDT\Engine\GDT::init($this->registry);
} catch (Exception $e) {
    // Логируем ошибку, но не прерываем выполнение
    error_log('GDT Framework init error: ' . $e->getMessage());
}
